"use client";

import React from "react";
import { CheckCircle2, ArrowRight } from "lucide-react";

export function CheckoutSuccessPage() {
  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-emerald-500/20 p-6 rounded-2xl shadow-xl select-none font-sans text-foreground flex flex-col items-center text-center">
      <div className="w-12 h-12 rounded-full bg-emerald-500/10 border border-emerald-500/20 flex items-center justify-center text-emerald-400 mb-4 animate-bounce">
        <CheckCircle2 className="w-6 h-6" />
      </div>

      <h4 className="text-sm font-black mb-1">Payment Successful!</h4>
      <p className="text-xs text-muted-foreground/60 max-w-[240px] leading-normal mb-5">Order confirmed. Tracking credentials sent to registered billing endpoints.</p>

      <button className="w-full py-2 bg-emerald-600 hover:bg-emerald-500 text-white font-bold text-xs rounded-xl flex items-center justify-center gap-1.5 transition-all">
        <span>Order Status Portal</span>
        <ArrowRight className="w-3.5 h-3.5" />
      </button>
    </div>
  );
}
